foreach($flag in $plan.contextFlags){$context=[Runtime.Serialization.StreamingContext]::new([Runtime.Serialization.StreamingContextStates]$flag);foreach($observe in $plan.observeMessage){for($index=0;$index -lt $plan.cases.Count;$index++){$spec=$plan.cases[$index];$message=$null;$fileName=$null;if($null -ne $plan.messages[$spec.messageIndex]){$message=[string]::new([char[]]([int[]]$plan.messages[$spec.messageIndex]))};if($null -ne $plan.files[$spec.fileIndex]){$fileName=[string]::new([char[]]([int[]]$plan.files[$spec.fileIndex]))};$inner=$null;if($spec.inner -eq 'plain'){$inner=[Exception]::new()}elseif($spec.inner -eq 'named'){$inner=[Exception]::new('inner')};$actual=$null;if($spec.inner -eq 'int'){$actual=[object][int]42}elseif($spec.inner -eq 'text'){$actual=[object]'selected actual'}elseif($spec.inner -eq 'hostile'){$actual=[Activator]::CreateInstance($spyType);$actual.Calls=$index};switch($spec.route){'actual'{$arguments=[object[]]::new(3);$arguments[0]=$fileName;$arguments[1]=$actual;$arguments[2]=$message};'default'{$arguments=[object[]]::new(0)};'message'{$arguments=[object[]]::new(1);$arguments[0]=$message};'inner'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$inner};'file'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$fileName};'file-inner'{$arguments=[object[]]::new(3);$arguments[0]=$message;$arguments[1]=$fileName;$arguments[2]=$inner}};if($spec.route -ne 'default' -and $null -eq $message){if($null -ne $arguments[2]){throw 'Null message coerced'};$nullArgumentControls++};$e=$constructors[$spec.family+':'+$spec.route].Invoke($arguments);if($observe){$null=$e.Message};$info=[Runtime.Serialization.SerializationInfo]::new($e.GetType(),[Runtime.Serialization.FormatterConverter]::new());$e.GetObjectData($info,$context);$entries=[Collections.Generic.List[object]]::new();$enumerator=$info.GetEnumerator();while($enumerator.MoveNext()){$entry=$enumerator.Current;$value=$entry.Value;$kind='null';$units=$null;$number=$null;if($null -ne $value){if($entry.Name -eq 'ActualValue'){if(-not [object]::ReferenceEquals($value,$actual)){throw 'ActualValue identity changed'};$kind='actual'}elseif([object]::ReferenceEquals($value,$inner)){$kind='inner'}elseif($value -is [string]){$kind='text';$units=[int[]][char[]]$value}elseif($value -is [int]){$kind='int';$number=$value}else{throw "Unexpected serialization value: $($entry.Name) $($value.GetType().FullName)"}};$entries.Add([ordered]@{name=$entry.Name;type=$entry.ObjectType.FullName;kind=$kind;units=$units;number=$number})};$callbackCalls=0;if($spec.inner -eq 'hostile'){$callbackCalls=$actual.Calls-$index;if($callbackCalls -ne 0){throw 'Serialization called ToString'}};$callbackPositiveVerified=$false;if($spec.inner -eq 'hostile'){try{$null=$actual.ToString();throw 'Expected hostile formatting failure'}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};if($errorValue -isnot [InvalidOperationException]){throw};if($actual.Calls -ne ($index+1)){throw 'Positive callback control failed'};$callbackPositiveVerified=$true}};$rows.Add([ordered]@{callbackPositiveVerified=$callbackPositiveVerified;callbackCalls=$callbackCalls;index=$index;contextFlag=$flag;observeMessage=[bool]$observe;memberCount=$info.MemberCount;entries=$entries.ToArray()})}};foreach($family in @('file')){$e=$constructors[$family+':default'].Invoke([object[]]@());try{$e.GetObjectData($null,$context);throw 'Expected null-info failure'}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};if($errorValue -isnot [ArgumentNullException]){throw};$controls.Add([ordered]@{family=$family;contextFlag=$flag;exception=$errorValue.GetType().FullName;paramName=$errorValue.ParamName;hResult=$errorValue.HResult;messageUnits=[int[]][char[]]$errorValue.Message})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';nullArgumentControls=$nullArgumentControls;rows=$rows.ToArray();controls=$controls.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 22 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS exception/file serialization: $($rows.Count) payloads and $($controls.Count) null controls"
